# Check whether expected output = most common NON-BG neighbor color, i.e. bg is treated as transparent/ignored
def solve2(I):
    H,W=len(I),len(I[0])
    I=np.array(I); bg=Counter(x for row in I for x in row).most_common(1)[0][0]
    out=[row[:] for row in I]
    seen=np.zeros_like(I,bool)
    def comps(A,bg):
        Hh,Ww=A.shape; seen=np.zeros_like(A,bool); res=[]
        for r in range(Hh):
            for c in range(Ww):
                if A[r,c]!=bg and not seen[r,c]:
                    st=[(r,c)]; seen[r,c]=True; vals=[]
                    while st:
                        p=st.pop(); vals.append((int(A[p[0],p[1]]),p[0],p[1]))
                        x,y=p[0],p[1]
                        for dr in(-1,0,1):
                            for dc in(-1,0,1):
                                rr,cc=x+dr,y+dc
                                if 0<=rr<Hh and 0<=cc<Ww and not seen[rr,cc] and A[rr,cc]==A[x][y]:
                                    seen[rr,cc]=True; st.append((rr,cc))
                    res.append(vals)
        return res
    cs=comps(I,bg)
    for comp in cs:
        if len(comp)==1:
            v,x,y=comp[0]
            cnt=Counter({int(I[i,j]) for i in range(max(0,x-1),min(H,x+2)) for j in range(max(0,y-1),min(W,y+2)) if abs(i-x)+abs(j-y)>0})
            # choose mode among non-bg neighbors only (break ties any)
            nbcnt={k:v for k,v in cnt.items() if k!=bg}
            if nbcnt:
                out[x][y]=max(nbcnt,key=nbcnt.get)
            else:
                out[x][y]=bg
    return [[int(x) for x in row] for row in out]
