    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))
def comps(A,bg):
    H,W=A.shape; seen=np.zeros_like(A,bool); res=[]
    for r in range(H):
        for c in range(W):
            if A[r][c]!=bg and not seen[r][c]:
                st=[(r,c)]; seen[r,c]=True; vals=[]
                while st:
                    p=st.pop(); vals.append(p)
                    x,y=p
                    for dr in(-1,0,1):
                        for dc in(-1,0,1):
                            rr,cc=x+dr,y+dc
                            if 0<=rr<H and 0<=cc<W and not seen[rr][cc] and A[rr][cc]==A[x][y]:
                                seen[rr][cc]=True; st.append((rr,cc))
                res.append(vals)
    return res
for name in ('Demo pair 1','Demo pair 2','Demo pair 3'):
    I=np.array(G[name+' input']); E=np.array(G[name+' output']); H,W=I.shape; bg=Counter(I.flatten()).most_common(1)[0][0]
    kept=set()
    for vals in comps(I,bg):
        if len(vals)>=2: kept.update(vals)
    ms=[(r,c,int(I[r][c]),int(E[r][c])) for r in range(H) for c in range(W) if int(E[r][c])!=int(I[r][c])]
    singles=[(r,c,i,e) for (r,c,i,e) in ms if (r,c) not in kept]
    print(name,'total misc:',len(ms),'singletons:',len(singles),'others:',len(ms)-len(singles))
    # which colors map where?
    from collections import defaultdict
    mapp=defaultdict(list)
    for (r,c,i,e) in singles:
        mapp[i].append(e)
    print('  color maps:',dict(mapp))

