def f_neigh(A):
    A=np.array(A); H,W=A.shape; out=[[0]*W for _ in range(H)]
    for r in range(H):
        for c in range(W):
            nb={}
            for i in(-1,0,1):
                for j in(-1,0,1):
                    rr,cc=r+i,c+j
                    if 0<=rr<H and 0<=cc<W: nb[int(A[rr][cc])]=nb.get(int(A[rr][cc]),0)+1
            m=max(nb,key=nb.get)
            out[r][c]=int(m)
    return [[int(x) for x in row] for row in out]
