    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        seg=t[m.end():]; rows=[r.split() for r in seg.split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
def solve(A):
    A=np.array(A); H,W=A.shape
    bg=collections.Counter(int(v) for v in A.flatten()).most_common(1)[0][0]
    seen=np.zeros_like(A,dtype=bool); res=[]
    for r in range(H):
        for c in range(W):
            if A[r,c]==bg or seen[r,c]: continue
            col=int(A[r,c]); stack=[(r,c)]; seen[r,c]=True; cells=[]
            while stack:
                y,x=stack.pop(); cells.append((y,x))
                for dy in(-1,0,1):
                    for dx in(-1,0,1):
                        yy_,xx_=y+dy,x+dx
                        if 0<=yy_<H and 0<=xx_<W and A[yy_,xx_]==col and not seen[yy_,xx_]:
                            seen[yy_,xx_]=True; stack.append((yy_,xx_))
            rs=[p[0] for p in cells]; cs=[p[1] for p in cells]
            res.append({'col':col,'size':len(cells),'bbox':(min(rs),max(rs),min(cs),max(cs))})
    out=[[bg]*W for _ in range(H)]
    for brr in range(H):
        for ccc in range(W):
            cand=[h for h in res if h['size']>1 and h['col']!=bg and h['bbox'][0]<=brr<=h['bbox'][1] and h['bbox'][2]<=ccc<=h['bbox'][3]]
            if cand:
                best=min(cand,key=lambda h:(-h['size'],-h['bbox'][0],-h['bbox'][2]))
                out[brr][ccc]=best['col']
            else: out[brr][ccc]=bg
    return out
