import numpy as np,collections,json
def solve(A):
    A=np.array(A); H,W=A.shape
    cnt=collections.Counter(int(v) for v in A.flatten()); bg=cnt.most_common(1)[0][0]
    seen=np.zeros_like(A,dtype=bool); out=[[bg]*W for _ in range(H)]
    for r in range(H):
        for c in range(W):
            if A[r,c]==bg or seen[r,c]: continue
            stack=[(r,c)]; seen[r,c]=True; cells=[]
            col=int(A[r,c])
            while stack:
                y,x=stack.pop(); cells.append((y,x))
                for dy in(-1,0,1):
                    for dx in(-1,0,1):
                        if dy==0 and dx==0: continue
                        yy_,xx_=y+dy,x+dx
                        if 0<=yy_<H and 0<=xx_<W and A[yy_,xx_]==col and not seen[yy_,xx_]:
                            seen[yy_,xx_]=True; stack.append((yy_,xx_))
            if len(cells)>1:
                for yy_,xx_ in cells: out[yy_][xx_]=col
            else:
                nb={}
                for dy2 in(-1,0,1):
                    for dx2 in(-1,0,1):
                        if dy2==0 and dx2==0: continue
                        yy_,xx_=y+dy2,x+dx2
                        if 0<=yy_<H and 0<=xx_<W: nb[int(A[yy_,xx_])]=nb.get(int(A[yy_,xx_]),0)+1
                out[y][x]=max(nb,key=nb.get)
    return [[int(x) for x in row] for row in out]
